var styleRuleHints = (language) => [
  ...new Set(STYLE_RULES[language].map((r) => r.hint))
];
function renderExample(c) {
  const lines = (label2, items) => items.length === 0 ? "" : `${label2}:
${items.map((item) => `  - ${item}`).join("\n")}
`;
  return `title: ${c.title}
technique: ${c.technique}   priority: ${c.priority}   acLabels: ${c.acLabels.join(", ")}
` + lines("preconditions", c.preconditions) + lines("testData", c.testData) + lines("steps", c.steps) + lines("expected", c.expected) + `whyEasyToMiss: ${c.whyEasyToMiss}`;
}
function languageStyle(language, name2) {
  const style = STYLES[language];
  return `# Style in ${name2}

${style.conventions}

Every case is checked against these rules after you write it:
${styleRuleHints(language).map((hint) => `- ${hint}`).join("\n")}

Rewritten from essay voice to sheet voice:
- not: ${style.contrast.no}
- but: ${style.contrast.yes}

When the spec does not say what should happen, the expected lines hold only what must be true whichever way it is decided, and the last expected line starts with "${SPEC_DECISION_LABEL[language]}:" and names the open question with its options. A status code, error name or message the spec does not give belongs in that last line, never above it.

Two cases in the voice to use. They show the voice and the level of detail only; their subject has nothing to do with the spec you are given.

<example_case>
${renderExample(style.examples[0])}
</example_case>
<example_case>
${renderExample(style.examples[1])}
</example_case>`;
}

// src/llm/prompts/user.ts
var RESERVED_TAGS = /<(\/?)(prd_documents|prd_document|acceptance_criteria|repo_instructions|glossary|pr_metadata|pr_title|pr_body|code_changes|changed_file|file_summary|hunk|code_context|skipped_files|partial_reports|partial_report|task)\b/gi;
var MAX_SKIPPED_LISTED = 300;
function guardData(text) {
  return text.replace(RESERVED_TAGS, "&lt;$1$2");
}
function attr(value) {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function buildPrdSection(context4) {
  if (context4.prdDocuments.length === 0) {
    return "<prd_documents>\n(No PRD is linked to this pull request.)\n</prd_documents>";
  }
  const docs = context4.prdDocuments.map((doc) => {
    const criteria = doc.acceptanceCriteria.length > 0 ? `
<acceptance_criteria>
${doc.acceptanceCriteria.map((ac) => `- ${guardData(ac)}`).join("\n")}
</acceptance_criteria>` : "";
    return `<prd_document id="${attr(doc.ref.id)}" source="${doc.ref.source}" title="${attr(doc.title)}">${criteria}
${guardData(doc.bodyMarkdown)}
</prd_document>`;
  });
  return `<prd_documents>
${docs.join("\n")}
</prd_documents>`;
}
function buildMetadataSection(context4) {
  const parts2 = [];
  const repo = context4.repoInstructions;
  const glossary = repo?.glossary ?? [];
  if (repo?.extraInstructions?.trim() || glossary.length > 0) {
    const lines = [];
    if (repo?.extraInstructions?.trim()) lines.push(guardData(repo.extraInstructions.trim()));
    if (glossary.length > 0) {
      lines.push(
        `<glossary>
${glossary.map((g) => `- ${guardData(g.term)}: ${guardData(g.meaning)}`).join("\n")}
</glossary>`
      );
    }
    parts2.push(`<repo_instructions>
${lines.join("\n")}
</repo_instructions>`);
  }
  const { pr } = context4;
  parts2.push(
    `<pr_metadata number="${pr.number}" author="${attr(pr.author)}" base="${attr(pr.baseRef)}" head="${attr(pr.headRef)}">
<pr_title>${guardData(pr.title)}</pr_title>
<pr_body>
${guardData(pr.body)}
</pr_body>
</pr_metadata>`
  );
  return parts2.join("\n");
}
function renderFile(file2) {
  const previous = file2.previousPath ? ` previous_path="${attr(file2.previousPath)}"` : "";
  const body2 = [];
  if (file2.summary) body2.push(`<file_summary>${guardData(file2.summary)}</file_summary>`);
  for (const hunk of file2.hunks) {
    body2.push(`<hunk header="${attr(hunk.header)}">
${guardData(hunk.text)}
</hunk>`);
  }
  for (const ctx of file2.contexts) {
    const name2 = ctx.name ? ` name="${attr(ctx.name)}"` : "";
    body2.push(
      `<code_context kind="${ctx.kind}"${name2} lines="${ctx.startLine}-${ctx.endLine}">
${guardData(ctx.text)}
</code_context>`
    );
  }
  return `<changed_file path="${attr(file2.path)}" status="${file2.status}"${previous}>
${body2.join("\n")}
</changed_file>`;
}
function buildCodeSection(chunk) {
  return `<code_changes>
${chunk.files.map(renderFile).join("\n")}
</code_changes>`;
}
function buildSkippedSection(skipped) {
  if (skipped.length === 0) return "<skipped_files>\n(none)\n</skipped_files>";
  const listed2 = skipped.slice(0, MAX_SKIPPED_LISTED).map((s) => `- ${guardData(s.path)} (${s.reason})`);
  if (skipped.length > MAX_SKIPPED_LISTED) {
    listed2.push(`(${skipped.length - MAX_SKIPPED_LISTED} more files not listed)`);
  }
  return `<skipped_files>
${listed2.join("\n")}
</skipped_files>`;
}
var MAX_P0_SCENARIOS = 5;
function buildScenarioLimit(maxScenarios) {
  const p0 = Math.min(MAX_P0_SCENARIOS, maxScenarios);
  if (p0 < maxScenarios) return `Return at most ${maxScenarios} scenarios, at most ${p0} of them P0.`;
  return `Return at most ${maxScenarios} ${maxScenarios === 1 ? "scenario" : "scenarios"}.`;
}
function buildTaskInstruction(phase, maxScenarios) {
  const scope = phase === "single" ? "Review the pull request above." : `Review this part of the pull request. The PR is too large for one pass, so it was split: you are seeing one part, the other parts are reviewed separately, and a final step merges the results. Judge only the files shown here. When a requirement's implementation is not in this part, mark the finding "unclear" and note that it may live in another part, because "missing" would be wrong if another part implements it.`;
  return `<task>
${scope} ${buildScenarioLimit(maxScenarios)}
</task>`;
}
function buildGenerateTail(req) {
  return [
    buildCodeSection(req.chunk),
    buildSkippedSection(req.skipped),
    buildTaskInstruction(req.phase, req.context.maxScenarios)
  ].join("\n");
}

